from pathlib import Path
from typing import Optional
import json
import logging

logger = logging.getLogger(__name__)

def safe_read_file(filepath: str | Path) -> Optional[str]:
    """EGRR_PATTERN: Safe file reading with comprehensive error handling."""
    path = Path(filepath)

    try:
        if not path.exists():
            logger.error(f'File not found: {path}')
            return None

        if not path.is_file():
            logger.error(f'Not a file: {path}')
            return None

        return path.read_text(encoding='utf-8')

    except PermissionError:
        logger.error(f'Permission denied: {path}')
        return None
    except UnicodeDecodeError as e:
        logger.error(f'Encoding error reading {path}: {e}')
        return None
    except OSError as e:
        logger.error(f'OS error reading {path}: {e}')
        return None

def safe_read_json(filepath: str | Path) -> Optional[dict]:
    """EGRR_PATTERN: Safe JSON file reading with validation."""
    content = safe_read_file(filepath)
    if content is None:
        return None

    try:
        data = json.loads(content)
        if not isinstance(data, dict):
            logger.error(f'JSON root is not an object: {filepath}')
            return None
        return data
    except json.JSONDecodeError as e:
        logger.error(f'Invalid JSON in {filepath}: {e}')
        return None

def safe_write_file(filepath: str | Path, content: str, create_dirs: bool = True) -> bool:
    """EGRR_PATTERN: Safe file writing with directory creation."""
    path = Path(filepath)

    try:
        if create_dirs:
            path.parent.mkdir(parents=True, exist_ok=True)

        path.write_text(content, encoding='utf-8')
        return True

    except PermissionError:
        logger.error(f'Permission denied writing to: {path}')
        return False
    except OSError as e:
        logger.error(f'OS error writing to {path}: {e}')
        return False
